//! `door.stranger-check`: proves a ce-wire door refuses strangers. For each api it learns the schema from a refusal,
//! then says Hello as nobody (empty token), as a fresh key nobody granted (a valid, self-signed proof), and asks the door
//! to spawn the cell as that stranger. PASS only when every one is refused and this machine's own key is accepted
//! (the control: a door that refuses everybody proves nothing). Types only: depend on this crate to call the cell;
//! Python and TypeScript clients are in sdk/ (generated by ce-wire-gen in CI). Op 1 is the health contract.

ce_wire::api! {
    api DoorStrangerCheck = "door.stranger-check", version 1;
    types {
        /// Health contract: these three fields, in this order, in every cell.
        pub struct Health { pub ok: bool, pub version: String, pub uptime_s: u64 }
        /// `addr`: a door, host:port (a door is :7700). `apis`: the cells to probe. `control`: also Hello with this
        /// machine's own key, which must be accepted (false when the door is on a machine that does not root ours).
        pub struct CheckReq { pub addr: String, pub apis: Vec<String>, pub control: bool }
        /// One probe. `who`: anonymous | stranger | stranger-spawn | own-key. `outcome`: REFUSED | OPEN | NO ANSWER |
        /// ACCEPTED (own key only) | SCHEMA ? (the schema could not be learned).
        pub struct Row { pub api: String, pub who: String, pub outcome: String, pub detail: String }
        /// `verdict`: PASS (every stranger refused, control accepted), OPEN (a stranger got in: the door is wrong),
        /// INCONCLUSIVE (a probe went unanswered, or the control was refused, so a refusal proves nothing).
        pub struct Report { pub addr: String, pub verdict: String, pub rows: Vec<Row> }
        pub enum CheckError { Invalid(String) }
    }
    ops {
        1 => HealthOp(()) -> Health, needs "door.stranger-check:health";
        2 => Check(CheckReq) -> Result<Report, CheckError>, needs "door.stranger-check:check";
    }
}
